contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint _value) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(_value <= address(c).balance);

        uint beforeBalance = address(c).balance;
        address beforeOwner = c.owner(); if (__ESBMC_reverted()) return;
        uint beforeCount = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint beforeThis = address(this).balance;

        c.withdraw(_value); if (__ESBMC_reverted()) return;

        assert(
            address(c).balance == beforeBalance - _value &&
            address(this).balance == beforeThis + _value &&
            c.owner() == beforeOwner &&
            c.depositsCount() == beforeCount
        );
    }

    receive() external payable {}
}

